package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/apache/iceberg-go"
	"github.com/apache/iceberg-go/catalog"
	sqlcat "github.com/apache/iceberg-go/catalog/sql"
	"github.com/apache/iceberg-go/table"
	_ "modernc.org/sqlite"
)

// Native fixture generated by DuckDB 2.0; exercise real v3 AddFiles and its
// day(time) inference locally, without Docker or changing any live catalog.
func TestNativePackV3AddFiles(t *testing.T) {
	input := os.Getenv("LAYOUT_TEST_INPUT")
	root := os.Getenv("LAYOUT_TEST_ROOT")
	if input == "" || root == "" {
		t.Skip("set LAYOUT_TEST_INPUT and isolated LAYOUT_TEST_ROOT")
	}
	ctx := context.Background()
	db, err := sql.Open("sqlite", filepath.Join(root, "catalog.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	cat, err := sqlcat.NewCatalog("layout-test", db, sqlcat.SQLite, iceberg.Properties{"warehouse": "file://" + root})
	if err != nil {
		t.Fatal(err)
	}
	if err = cat.CreateNamespace(ctx, table.Identifier{"sage"}, nil); err != nil {
		t.Fatal(err)
	}
	fields := []iceberg.NestedField{{ID: 1, Name: "time", Type: iceberg.TimestampTzNsType{}}}
	names := []string{"name", "plugin", "vsn", "node", "host", "task", "job", "zone"}
	for i, name := range names {
		fields = append(fields, iceberg.NestedField{ID: i + 2, Name: name, Type: iceberg.PrimitiveTypes.String})
	}
	fields = append(fields, iceberg.NestedField{ID: 10, Name: "meta", Type: &iceberg.MapType{KeyID: 12, KeyType: iceberg.PrimitiveTypes.String, ValueID: 13, ValueType: iceberg.PrimitiveTypes.String}}, iceberg.NestedField{ID: 11, Name: "value", Type: iceberg.VariantType{}})
	sc := iceberg.NewSchema(0, fields...)
	spec := iceberg.NewPartitionSpec(iceberg.PartitionField{SourceIDs: []int{1}, FieldID: 1000, Name: "day_time", Transform: iceberg.DayTransform{}})
	tbl, err := cat.CreateTable(ctx, table.Identifier{"sage", "obs"}, sc, catalog.WithProperties(iceberg.Properties{"format-version": "3", "sage.layout": "plugin-vsn-time", "sage.row-group.rows": "100000"}), catalog.WithPartitionSpec(&spec))
	if err != nil {
		t.Fatal(err)
	}
	// CreateTable assigns IDs depth-first. Our real table is created by
	// DuckDB, which assigns top-level IDs first (value=11, map children=12/13).
	// Adjust only this empty local fixture to that schema before AddFiles.
	initial := strings.TrimPrefix(tbl.MetadataLocation(), "file://")
	raw, err := os.ReadFile(initial)
	if err != nil {
		t.Fatal(err)
	}
	var doc map[string]any
	if err = json.Unmarshal(raw, &doc); err != nil {
		t.Fatal(err)
	}
	doc["schemas"] = []*iceberg.Schema{sc}
	doc["current-schema-id"] = 0
	doc["last-column-id"] = 13
	raw, err = json.Marshal(doc)
	if err != nil {
		t.Fatal(err)
	}
	if err = os.WriteFile(initial, raw, 0644); err != nil {
		t.Fatal(err)
	}
	tbl, err = cat.LoadTable(ctx, table.Identifier{"sage", "obs"})
	if err != nil {
		t.Fatal(err)
	}
	output := filepath.Join(strings.TrimPrefix(tbl.Location(), "file://"), "data", "batch.parquet")
	if err = pack(ctx, input, output, 100000); err != nil {
		t.Fatal(err)
	}
	tx := tbl.NewTransaction()
	if err = tx.AddFiles(ctx, []string{output}, nil, false, table.WithAddFilesConcurrency(1)); err != nil {
		t.Fatal(err)
	}
	committed, err := tx.Commit(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if committed.Metadata().Version() != 3 {
		t.Fatal("lost v3")
	}
	tasks, err := committed.Scan().PlanFiles(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(tasks) != 1 {
		t.Fatalf("expected one registered file, got %d", len(tasks))
	}
	if err = os.WriteFile(filepath.Join(root, "head.txt"), []byte(committed.MetadataLocation()), 0644); err != nil {
		t.Fatal(err)
	}
}
